#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<string> g(n);              // 'X' = źródło (np. sklep), '#' = ściana, '.' = wolne
    for (auto& r : g) cin >> r;
    const int dx[4] = {-1, 0, 1, 0}, dy[4] = {0, 1, 0, -1};
    vector<vector<int>> dist(n, vector<int>(m, -1));
    queue<pair<int, int>> q;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++)
            if (g[i][j] == 'X') {     // WSZYSTKIE źródła na start, każde z odległością 0
                dist[i][j] = 0;
                q.push({i, j});
            }
    while (!q.empty()) {              // dalej zwykły BFS
        auto [x, y] = q.front();
        q.pop();
        for (int d = 0; d < 4; d++) {
            int nx = x + dx[d], ny = y + dy[d];
            if (nx < 0 || nx >= n || ny < 0 || ny >= m) continue;
            if (g[nx][ny] == '#' || dist[nx][ny] != -1) continue;
            dist[nx][ny] = dist[x][y] + 1;
            q.push({nx, ny});
        }
    }
    for (int i = 0; i < n; i++)       // -1 = żadne źródło nie dociera
        for (int j = 0; j < m; j++)
            cout << dist[i][j] << " \n"[j == m - 1];
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, m, k;
    cin >> n >> m >> k;
    vector<int> src(k);                       // różne wierzchołki specjalne
    for (auto& s : src) cin >> s;
    vector<vector<int>> adj(n + 1);
    vector<pair<int, int>> edges(m);
    for (auto& [a, b] : edges) {
        cin >> a >> b;
        adj[a].push_back(b);
        adj[b].push_back(a);
    }
    vector<int> dist(n + 1, -1), owner(n + 1, -1);   // owner[v] = najbliższe źródło
    queue<int> q;
    for (int s : src) {
        dist[s] = 0;
        owner[s] = s;
        q.push(s);
    }
    while (!q.empty()) {
        int v = q.front();
        q.pop();
        for (int u : adj[v])
            if (dist[u] == -1) {
                dist[u] = dist[v] + 1;
                owner[u] = owner[v];          // u dziedziczy źródło po v
                q.push(u);
            }
    }
    for (int v = 1; v <= n; v++)
        cout << v << ": dist=" << dist[v] << " zrodlo=" << owner[v] << '\n';
    // najbliższa para RÓŻNYCH źródeł = krawędź na granicy dwóch „stref”
    int best = INT_MAX;
    for (auto [a, b] : edges)
        if (dist[a] != -1 && dist[b] != -1 && owner[a] != owner[b])
            best = min(best, dist[a] + 1 + dist[b]);
    cout << "najblizsza para zrodel: " << (best == INT_MAX ? -1 : best) << '\n';
}

#include <bits/stdc++.h>
using namespace std;

const int dx[4] = {-1, 0, 1, 0}, dy[4] = {0, 1, 0, -1};
int n, m;
vector<string> g;            // '.' wolne, '#' ściana, 'F' ogień, 'A' ja

// BFS z wielu źródeł: start ze wszystkich pól z literą c (czas 0).
// fire != nullptr: wolno wejść na pole tylko PRZED ogniem.
vector<vector<int>> bfs(char c, const vector<vector<int>>* fire) {
    vector<vector<int>> d(n, vector<int>(m, INT_MAX));
    queue<pair<int, int>> q;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++)
            if (g[i][j] == c) { d[i][j] = 0; q.push({i, j}); }
    while (!q.empty()) {
        auto [x, y] = q.front();
        q.pop();
        for (int k = 0; k < 4; k++) {
            int nx = x + dx[k], ny = y + dy[k];
            if (nx < 0 || nx >= n || ny < 0 || ny >= m || g[nx][ny] == '#') continue;
            if (d[nx][ny] != INT_MAX) continue;
            int t = d[x][y] + 1;
            if (fire && t >= (*fire)[nx][ny]) continue;   // ogień był tam wcześniej lub dociera w tej chwili
            d[nx][ny] = t;
            q.push({nx, ny});
        }
    }
    return d;
}

int main() {
    cin >> n >> m;
    g.resize(n);
    for (auto& r : g) cin >> r;
    auto fire = bfs('F', nullptr);      // 1) kiedy ogień dociera do każdego pola
    auto me = bfs('A', &fire);          // 2) kiedy ja mogę tam bezpiecznie stanąć
    int best = INT_MAX;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++)
            if ((i == 0 || j == 0 || i == n - 1 || j == m - 1) && me[i][j] != INT_MAX)
                best = min(best, me[i][j]);
    if (best == INT_MAX) cout << "NIE\n";
    else cout << best << '\n';          // liczba ruchów do pola na brzegu planszy
}

