#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<string> g(n);
    for (auto& r : g) cin >> r;
    const char LAD = '#';                              // znak pola należącego do obszaru (wyspy)
    const int dx[4] = {-1, 0, 1, 0}, dy[4] = {0, 1, 0, -1};
    vector<vector<int>> comp(n, vector<int>(m, -1));   // numer obszaru pola albo -1
    vector<int> sz;                                    // sz[c] = liczba pól obszaru c
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++) {
            if (g[i][j] != LAD || comp[i][j] != -1) continue;
            int c = sz.size();                         // nieodwiedzony ląd = nowy obszar
            sz.push_back(0);
            queue<pair<int, int>> q;
            comp[i][j] = c;                            // oznaczamy PRZY wrzucaniu do kolejki
            q.push({i, j});
            while (!q.empty()) {
                auto [x, y] = q.front();
                q.pop();
                sz[c]++;
                for (int d = 0; d < 4; d++) {
                    int nx = x + dx[d], ny = y + dy[d];
                    if (nx < 0 || nx >= n || ny < 0 || ny >= m) continue;
                    if (g[nx][ny] != LAD || comp[nx][ny] != -1) continue;
                    comp[nx][ny] = c;
                    q.push({nx, ny});
                }
            }
        }
    cout << sz.size() << '\n';                                               // liczba wysp
    cout << (sz.empty() ? 0 : *max_element(sz.begin(), sz.end())) << '\n';   // największa wyspa
}

int n, m;
vector<string> g;
vector<vector<bool>> vis;
int dfs(int x, int y) {                              // zwraca rozmiar obszaru
    if (x < 0 || x >= n || y < 0 || y >= m) return 0;
    if (g[x][y] != '#' || vis[x][y]) return 0;
    vis[x][y] = true;
    return 1 + dfs(x + 1, y) + dfs(x - 1, y) + dfs(x, y + 1) + dfs(x, y - 1);
}

#include <bits/stdc++.h>
using namespace std;

vector<int> par, sz;
int findp(int v) { return par[v] == v ? v : par[v] = findp(par[v]); }
bool unite(int a, int b) {
    a = findp(a), b = findp(b);
    if (a == b) return false;
    if (sz[a] < sz[b]) swap(a, b);
    par[b] = a;
    sz[a] += sz[b];
    return true;
}

int main() {
    int n, m, q;
    cin >> n >> m >> q;                    // plansza n×m, na początku sama woda
    par.resize(n * m);
    sz.assign(n * m, 1);
    iota(par.begin(), par.end(), 0);
    vector<char> land(n * m, 0);
    const int dx[4] = {-1, 0, 1, 0}, dy[4] = {0, 1, 0, -1};
    int islands = 0;
    while (q--) {
        int x, y;
        cin >> x >> y;                     // pole (x, y) staje się lądem (0-indeksowane)
        int id = x * m + y;
        if (!land[id]) {
            land[id] = 1;
            islands++;                     // nowa wyspa z jednego pola...
            for (int d = 0; d < 4; d++) {
                int nx = x + dx[d], ny = y + dy[d];
                if (nx < 0 || nx >= n || ny < 0 || ny >= m) continue;
                int nid = nx * m + ny;
                if (land[nid] && unite(id, nid)) islands--;   // ...sklejana z sąsiednimi
            }
        }
        cout << islands << '\n';
    }
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<string> g(n);                       // '.' woda, '#' ląd
    for (auto& r : g) cin >> r;
    int dx[4] = {-1, 0, 1, 0}, dy[4] = {0, 1, 0, -1};
    vector<vector<char>> vis(n, vector<char>(m, 0));
    auto fill = [&](int sx, int sy) {          // zalewa obszar wody od (sx, sy)
        queue<pair<int, int>> q;
        vis[sx][sy] = 1;
        q.push({sx, sy});
        while (!q.empty()) {
            auto [x, y] = q.front();
            q.pop();
            for (int d = 0; d < 4; d++) {
                int nx = x + dx[d], ny = y + dy[d];
                if (nx < 0 || nx >= n || ny < 0 || ny >= m) continue;
                if (g[nx][ny] != '.' || vis[nx][ny]) continue;
                vis[nx][ny] = 1;
                q.push({nx, ny});
            }
        }
    };
    for (int i = 0; i < n; i++)                // 1) zalej wodę połączoną z brzegiem (morze)
        for (int j = 0; j < m; j++)
            if ((i == 0 || j == 0 || i == n - 1 || j == m - 1) && g[i][j] == '.' && !vis[i][j])
                fill(i, j);
    int lakes = 0;                             // 2) każdy pozostały obszar wody to jezioro
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++)
            if (g[i][j] == '.' && !vis[i][j]) { lakes++; fill(i, j); }
    cout << lakes << '\n';
}

