#include <bits/stdc++.h>
using namespace std;

const int MAXN = 16;
const long long INF = LLONG_MAX / 4;
long long dp[1 << MAXN][MAXN];   // dp[mask][v] = min koszt ścieżki z 0 przez DOKŁADNIE mask, kończącej się w v
int par[1 << MAXN][MAXN];        // poprzednik v na tej ścieżce (do odtworzenia)

int main() {
    int n;
    cin >> n;                                     // n <= 16, miasta 0..n-1
    vector<vector<long long>> c(n, vector<long long>(n));
