#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

const int LOG = 18;                     // 2^18 > 2·10^5
const ll INF = LLONG_MAX / 4;
vector<vector<pair<int, int>>> g;       // (sąsiad, waga)
vector<int> tin, dep;
vector<ll> mn;                          // mn[v] = najtańsza krawędź na ścieżce korzeń -> v
vector<array<int, LOG>> up;

int lca(int a, int b) {
    if (dep[a] < dep[b]) swap(a, b);
    for (int k = LOG - 1; k >= 0; k--)
        if (dep[a] - (1 << k) >= dep[b]) a = up[a][k];
    if (a == b) return a;
    for (int k = LOG - 1; k >= 0; k--)
        if (up[a][k] != up[b][k]) a = up[a][k], b = up[b][k];
    return up[a][0];
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    g.resize(n + 1);
    for (int i = 0; i < n - 1; i++) {
        int a, b, w;
        cin >> a >> b >> w;
        g[a].push_back({b, w});
        g[b].push_back({a, w});
    }
    tin.assign(n + 1, 0); dep.assign(n + 1, 0); mn.assign(n + 1, INF); up.resize(n + 1);
    vector<char> seen(n + 1, 0);
    vector<int> st = {1};               // DFS iteracyjny od korzenia 1; kolejność zdejmowania = preorder
    seen[1] = 1;
    up[1].fill(1);
    int timer = 0;
    while (!st.empty()) {
        int v = st.back();
        st.pop_back();
        tin[v] = timer++;
        for (auto [u, w] : g[v])
            if (!seen[u]) {
                seen[u] = 1;
                dep[u] = dep[v] + 1;
                mn[u] = min(mn[v], (ll)w);
                up[u][0] = v;
                for (int k = 1; k < LOG; k++) up[u][k] = up[up[u][k - 1]][k - 1];
                st.push_back(u);
            }
    }

    vector<vector<int>> ch(n + 1);      // dzieci w drzewie WIRTUALNYM
    vector<char> marked(n + 1, 0);
    vector<ll> dp(n + 1, 0);
    auto byTin = [&](int a, int b) { return tin[a] < tin[b]; };
    int q;
    cin >> q;
    while (q--) {
        int k;
        cin >> k;
        vector<int> vs(k);
        for (auto& v : vs) { cin >> v; marked[v] = 1; }   // zaznaczone (różne od korzenia 1)
        vs.push_back(1);                                  // korzeń zawsze w drzewie wirtualnym
        // 1) sortuj po tin, 2) dodaj LCA sąsiednich, 3) sortuj i usuń powtórzenia
        sort(vs.begin(), vs.end(), byTin);
        int s = vs.size();
        for (int i = 0; i + 1 < s; i++) vs.push_back(lca(vs[i], vs[i + 1]));
        sort(vs.begin(), vs.end(), byTin);
        vs.erase(unique(vs.begin(), vs.end()), vs.end());
        // 4) ojciec vs[i] w drzewie wirtualnym = lca(vs[i-1], vs[i])
        for (int i = 1; i < (int)vs.size(); i++) ch[lca(vs[i - 1], vs[i])].push_back(vs[i]);
        // DP od liści: odwrotna kolejność tin = dzieci przed rodzicem
        for (int i = (int)vs.size() - 1; i >= 0; i--) {
            int v = vs[i];
            ll sum = 0;
            for (int c : ch[v]) sum += dp[c];
            dp[v] = marked[v] ? mn[v] : min(mn[v], sum);  // odetnij nad v albo w każdym poddrzewie
        }
        cout << dp[1] << '\n';
        for (int v : vs) { ch[v].clear(); marked[v] = 0; } // sprzątamy TYLKO użyte wierzchołki
    }
}

