#include <bits/stdc++.h>
using namespace std;

map<vector<int>, int> ids;   // WSPÓLNA dla obu drzew: posortowane numery dzieci -> numer kształtu

// AHU: numer kształtu (postać kanoniczna) drzewa g ukorzenionego w root; bez rekurencji
int canon(const vector<vector<int>>& g, int root) {
    int n = g.size();
    vector<int> order = {root}, par(n, -1), id(n);
    vector<vector<int>> kids(n);
    par[root] = root;
    for (int i = 0; i < (int)order.size(); i++)          // BFS: rodzic przed dziećmi
        for (int u : g[order[i]])
            if (par[u] == -1) { par[u] = order[i]; order.push_back(u); }
    for (int i = n - 1; i >= 0; i--) {                    // od liści w górę
        int v = order[i];
        sort(kids[v].begin(), kids[v].end());
        auto it = ids.find(kids[v]);
        if (it == ids.end()) it = ids.emplace(kids[v], (int)ids.size()).first;
        id[v] = it->second;
        if (v != root) kids[par[v]].push_back(id[v]);
    }
    return id[root];
}

vector<int> centers(const vector<vector<int>>& g) {       // 1 lub 2 środki (obcinanie liści)
    int n = g.size();
    if (n == 1) return {0};
    vector<int> deg(n), leaves;
    for (int v = 0; v < n; v++) {
        deg[v] = g[v].size();
        if (deg[v] == 1) leaves.push_back(v);
    }
    int left = n;
    while (left > 2) {
        left -= leaves.size();
        vector<int> nxt;
        for (int v : leaves)
            for (int u : g[v])
                if (--deg[u] == 1) nxt.push_back(u);
        leaves = nxt;
    }
    return leaves;
}

vector<vector<int>> readTree(int n) {
    vector<vector<int>> g(n);
    for (int i = 0; i < n - 1; i++) {
        int a, b;
        cin >> a >> b;
        g[a - 1].push_back(b - 1);
        g[b - 1].push_back(a - 1);
    }
    return g;
}

int main() {
    int n;
    cin >> n;
    auto A = readTree(n), B = readTree(n);
    auto ca = centers(A), cb = centers(B);
    bool ok = false;
    if (ca.size() == cb.size()) {
        int ha = canon(A, ca[0]);                         // jeden środek A...
        for (int c : cb) if (canon(B, c) == ha) ok = true; // ...porównaj z każdym środkiem B
    }
    cout << (ok ? "TAK" : "NIE") << '\n';
}

const uint64_t SEED = chrono::steady_clock::now().time_since_epoch().count();
uint64_t mix(uint64_t x) {                       // splitmix64
    x += 0x9e3779b97f4a7c15ULL;
    x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ULL;
    x = (x ^ (x >> 27)) * 0x94d049bb133111ebULL;
    return x ^ (x >> 31);
}
// h[v] = 1 + suma mix(h[dziecko] ^ SEED): suma jest przemienna, więc kolejność dzieci nie ma znaczenia
vector<uint64_t> treeHash(const vector<vector<int>>& g, int root) {
    int n = g.size();
    vector<int> order = {root}, par(n, -1);
    par[root] = root;
    for (int i = 0; i < (int)order.size(); i++)
        for (int u : g[order[i]])
            if (par[u] == -1) { par[u] = order[i]; order.push_back(u); }
    vector<uint64_t> h(n, 1);
    for (int i = n - 1; i > 0; i--) {            // order[0] = root; dzieci przed rodzicem
        int v = order[i];
        h[par[v]] += mix(h[v] ^ SEED);
    }
    return h;                                    // h[v] = hash poddrzewa v
}

