#include <bits/stdc++.h>
using namespace std;

struct WeightedDSU {
    vector<int> p, sz;
    vector<long long> d;                       // d[v] = x[v] - x[p[v]]
    WeightedDSU(int n) : p(n), sz(n, 1), d(n, 0) { iota(p.begin(), p.end(), 0); }
    int find(int v) {                          // po find: p[v] = korzeń, d[v] = x[v] - x[korzeń]
        if (p[v] == v) return v;
        int r = find(p[v]);
        d[v] += d[p[v]];                       // NAJPIERW doliczamy wagę rodzica (już względem korzenia)
        return p[v] = r;                       // dopiero potem przepinamy v pod korzeń
    }
    // dodaje warunek x[b] - x[a] = w; zwraca false, gdy jest sprzeczny z wcześniejszymi
    bool unite(int a, int b, long long w) {
        int ra = find(a), rb = find(b);
        long long pa = d[a], pb = d[b];        // x[a] - x[ra], x[b] - x[rb]
        if (ra == rb) return pb - pa == w;
        if (sz[ra] < sz[rb]) { swap(ra, rb); swap(pa, pb); w = -w; }
        p[rb] = ra;                            // rb pod ra: x[rb] - x[ra] = w + pa - pb
        sz[ra] += sz[rb];
        d[rb] = w + pa - pb;
        return true;
    }
    bool same(int a, int b) { return find(a) == find(b); }
    long long diff(int a, int b) { find(a); find(b); return d[b] - d[a]; }   // x[b] - x[a], gdy same(a, b)
};

int main() {
    int n, q;
    cin >> n >> q;
    WeightedDSU dsu(n + 1);
    while (q--) {
        char t;
        int a, b;
        cin >> t >> a >> b;
        if (t == '!') {                        // "! a b w": b jest o w cięższe od a
            long long w;
            cin >> w;
            if (!dsu.unite(a, b, w)) cout << "SPRZECZNOSC\n";
        } else {                               // "? a b": ile wynosi x[b] - x[a]
            if (dsu.same(a, b)) cout << dsu.diff(a, b) << '\n';
            else cout << "NIEZNANE\n";
        }
    }
}

