#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

const int LOG = 18;                              // 2^18 > 2·10^5
vector<int> dsu;
int findp(int v) { return dsu[v] == v ? v : dsu[v] = findp(dsu[v]); }

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;                               // graf spójny, wagi >= 0
    vector<array<int, 3>> e(m);                  // {u, v, w}
    for (auto& [u, v, w] : e) cin >> u >> v >> w;
    // 1) Kruskal: MST o wadze W
    vector<int> ord(m);
    iota(ord.begin(), ord.end(), 0);
    sort(ord.begin(), ord.end(), [&](int a, int b) { return e[a][2] < e[b][2]; });
    dsu.resize(n + 1);
    iota(dsu.begin(), dsu.end(), 0);
    vector<vector<pair<int, int>>> t(n + 1);     // MST: (sąsiad, waga)
    ll W = 0;
    for (int i : ord) {
        auto [u, v, w] = e[i];
        if (findp(u) == findp(v)) continue;
        dsu[findp(u)] = findp(v);
        W += w;
        t[u].push_back({v, w});
        t[v].push_back({u, w});
    }
    // 2) binary lifting po MST: up[v][k] = przodek o 2^k, mx[v][k] = max waga na tych 2^k krawędziach
    vector<array<int, LOG>> up(n + 1), mx(n + 1);
    vector<int> dep(n + 1, -1);
    vector<int> st = {1};
    dep[1] = 0;
    up[1].fill(1);
    mx[1].fill(0);
    while (!st.empty()) {
        int v = st.back();
        st.pop_back();
        for (auto [u, w] : t[v])
            if (dep[u] == -1) {
                dep[u] = dep[v] + 1;
                up[u][0] = v;
                mx[u][0] = w;
                for (int k = 1; k < LOG; k++) {
                    up[u][k] = up[up[u][k - 1]][k - 1];
                    mx[u][k] = max(mx[u][k - 1], mx[up[u][k - 1]][k - 1]);
                }
                st.push_back(u);
            }
    }
    auto pathMax = [&](int a, int b) {           // max waga krawędzi na ścieżce a–b w MST
        int res = 0;
        if (dep[a] < dep[b]) swap(a, b);
        for (int k = LOG - 1; k >= 0; k--)
            if (dep[a] - (1 << k) >= dep[b]) { res = max(res, mx[a][k]); a = up[a][k]; }
        if (a == b) return res;
        for (int k = LOG - 1; k >= 0; k--)
            if (up[a][k] != up[b][k]) {
                res = max({res, mx[a][k], mx[b][k]});
                a = up[a][k];
                b = up[b][k];
            }
        return max({res, mx[a][0], mx[b][0]});
    };
    // 3) najlżejsze drzewo rozpinające ZAWIERAJĄCE krawędź (u, v, w): W - pathMax(u, v) + w
    for (auto [u, v, w] : e) cout << W - pathMax(u, v) + w << '\n';
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

const int LOG = 18;
const int NEG = INT_MIN;                         // „brak wartości”
typedef pair<int, int> Top2;                     // {największa, druga ŚCIŚLE mniejsza}
Top2 comb(Top2 a, Top2 b) {
    int v[4] = {a.first, a.second, b.first, b.second};
    int m1 = *max_element(v, v + 4), m2 = NEG;
    for (int x : v)
        if (x < m1) m2 = max(m2, x);
    return {m1, m2};
}
vector<int> dsu;
int findp(int v) { return dsu[v] == v ? v : dsu[v] = findp(dsu[v]); }

int main() {
    int n, m;
    cin >> n >> m;                               // graf spójny
    vector<array<int, 3>> e(m);
    for (auto& [u, v, w] : e) cin >> u >> v >> w;
    sort(e.begin(), e.end(), [](const auto& a, const auto& b) { return a[2] < b[2]; });
    dsu.resize(n + 1);
    iota(dsu.begin(), dsu.end(), 0);
    vector<vector<pair<int, int>>> t(n + 1);
    vector<bool> inTree(m, false);
    ll W = 0;
    for (int i = 0; i < m; i++) {
        auto [u, v, w] = e[i];
        if (findp(u) == findp(v)) continue;
        dsu[findp(u)] = findp(v);
        W += w;
        inTree[i] = true;
        t[u].push_back({v, w});
        t[v].push_back({u, w});
    }
    vector<array<int, LOG>> up(n + 1);
    vector<array<Top2, LOG>> mx(n + 1);
    vector<int> dep(n + 1, -1);
    vector<int> st = {1};
    dep[1] = 0;
    up[1].fill(1);
    mx[1].fill({NEG, NEG});
    while (!st.empty()) {
        int v = st.back();
        st.pop_back();
        for (auto [u, w] : t[v])
            if (dep[u] == -1) {
                dep[u] = dep[v] + 1;
                up[u][0] = v;
                mx[u][0] = {w, NEG};
                for (int k = 1; k < LOG; k++) {
                    up[u][k] = up[up[u][k - 1]][k - 1];
                    mx[u][k] = comb(mx[u][k - 1], mx[up[u][k - 1]][k - 1]);
                }
                st.push_back(u);
            }
    }
    auto path = [&](int a, int b) {              // dwie największe RÓŻNE wagi na ścieżce a–b
        Top2 r = {NEG, NEG};
        if (dep[a] < dep[b]) swap(a, b);
        for (int k = LOG - 1; k >= 0; k--)
            if (dep[a] - (1 << k) >= dep[b]) { r = comb(r, mx[a][k]); a = up[a][k]; }
        if (a == b) return r;
        for (int k = LOG - 1; k >= 0; k--)
            if (up[a][k] != up[b][k]) {
                r = comb(r, comb(mx[a][k], mx[b][k]));
                a = up[a][k];
                b = up[b][k];
            }
        return comb(r, comb(mx[a][0], mx[b][0]));
    };
    ll best = LLONG_MAX;                         // ŚCIŚLE drugie MST
    for (int i = 0; i < m; i++) {
        if (inTree[i]) continue;
        auto [u, v, w] = e[i];
        if (u == v) continue;                    // pętla nie wchodzi do żadnego drzewa
        auto [m1, m2] = path(u, v);
        if (w > m1) best = min(best, W - m1 + w);            // wymiana z największą krawędzią
        else if (m2 != NEG) best = min(best, W - m2 + w);    // w == m1: wymiana z drugą największą
    }
    cout << W << ' ' << (best == LLONG_MAX ? -1 : best) << '\n';   // -1: brak ściśle gorszego drzewa
}

