            if (a != b) p[a] = b;
        }
    }
    return res;
}

// wolna, ale prosta wersja O(m · m · α): czy krawędź i jest w KAŻDYM MST
bool inEveryMST(int n, const vector<array<int, 3>>& e, int i) {
    vector<int> p(n + 1);
    iota(p.begin(), p.end(), 0);
    function<int(int)> f = [&](int v) { return p[v] == v ? v : p[v] = f(p[v]); };
    for (int j = 0; j < (int)e.size(); j++)
        if (j != i && e[j][2] <= e[i][2]) p[f(e[j][0])] = f(e[j][1]);
    return f(e[i][0]) != f(e[i][1]);
}

