// max waga na ścieżce u–v w MST (= minimax u–v w grafie) = val[lca(u, v)] w tym drzewie.
void buildKRT(int n, vector<array<int, 3>> e, vector<int>& par, vector<int>& val) {
    sort(e.begin(), e.end(), [](const auto& a, const auto& b) { return a[2] < b[2]; });
    vector<int> d(2 * n);
    iota(d.begin(), d.end(), 0);
    function<int(int)> f = [&](int v) { return d[v] == v ? v : d[v] = f(d[v]); };
    par.assign(2 * n, -1);
    val.assign(2 * n, 0);
    int cnt = n;
    for (auto [u, v, w] : e) {
        int a = f(u), b = f(v);
        if (a == b) continue;
        val[cnt] = w;
        par[a] = par[b] = cnt;                   // nowy węzeł nad dwoma łączonymi zbiorami
