        int a, b, c;
        cin >> a >> b >> c;
        g[a].push_back({b, c});
    }
    vector<int> cnt(n + 1, 0);                    // ile razy wierzchołek zszedł już z kolejki
    priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<>> pq;
    pq.push({0, 1});
    vector<ll> ans;
    while (!pq.empty() && cnt[n] < k) {
        auto [d, v] = pq.top();
        pq.pop();
        if (cnt[v] >= k) continue;                // v ma już k najlepszych tras — reszta zbędna
        cnt[v]++;
        if (v == n) ans.push_back(d);             // j-te zdjęcie n = j-ta najkrótsza trasa
        for (auto [u, w] : g[v])
            if (cnt[u] < k) pq.push({d + w, u});
    }
    for (ll x : ans) cout << x << ' ';            // niemalejąco; mniej niż k, jeśli tylu tras nie ma
    cout << '\n';
}

