int n = 3, K = 2;
vector<vector<pair<int, int>>> g(n + 1);
g[1] = {{2, 1}, {3, 5}}; g[2] = {{3, 1}};
vector<int> cnt(n + 1, 0);
priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<>> pq;
pq.push({0, 1});
while (!pq.empty() && cnt[n] < K) {
    auto [d, v] = pq.top(); pq.pop();
    if (cnt[v] >= K) continue;
    cnt[v]++;
    if (v == n) cout << d << ' ';                 // 2 5
    for (auto [u, w] : g[v]) if (cnt[u] < K) pq.push({d + w, u});
}

typedef long long ll;
const ll INF = LLONG_MAX / 4;
// ds = odległości od s, dt = odległości do t, D = ds[t]; INF = brak takiej trasy
ll secondShortest(const vector<array<int, 3>>& edges, const vector<ll>& ds, const vector<ll>& dt, ll D) {
    ll best = INF;
    for (auto [u, v, w] : edges) {               // nieskierowany: podaj obie orientacje
        if (ds[u] >= INF || dt[v] >= INF) continue;
        ll L = ds[u] + w + dt[v];
        if (L > D) best = min(best, L);
    }
    return best;
}

// ds = odległości od s, dt = odległości do t, D = ds[t]; zwraca indeksy krawędzi
vector<int> naNajkrotszej(const vector<array<long long, 3>>& e, const vector<long long>& ds,
                          const vector<long long>& dt, long long D) {
    const long long INF = LLONG_MAX / 4;
    vector<int> res;
    for (int i = 0; i < (int)e.size(); i++) {
        auto [u, v, w] = e[i];
        if (ds[u] < INF && dt[v] < INF && ds[u] + w + dt[v] == D) res.push_back(i);
    }
    return res;
}

const long long MOD = 1e9 + 7;
// d[v] = odległość od s, ways[v] = liczba najkrótszych ścieżek s -> v (mod MOD); wagi > 0
void countShortest(const vector<vector<pair<int, int>>>& g, int s, vector<long long>& d, vector<long long>& ways) {
    int n = g.size();
    d.assign(n, LLONG_MAX);
    ways.assign(n, 0);
    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<>> pq;
    d[s] = 0;
    ways[s] = 1;
    pq.push({0, s});
    while (!pq.empty()) {
        auto [dd, v] = pq.top();
        pq.pop();
        if (dd > d[v]) continue;
        for (auto [u, w] : g[v]) {
            if (dd + w < d[u]) { d[u] = dd + w; ways[u] = ways[v]; pq.push({d[u], u}); }
            else if (dd + w == d[u]) ways[u] = (ways[u] + ways[v]) % MOD;
        }
    }
}

